1	package net.officefloor.hq.app.claim;
2	
3	import jakarta.validation.Valid;
4	import jakarta.validation.constraints.NotBlank;
5	import jakarta.validation.constraints.NotNull;
6	import jakarta.validation.constraints.Pattern;
7	import jakarta.validation.constraints.Size;
8	import java.math.BigDecimal;
9	import java.math.RoundingMode;
10	import java.time.LocalDate;
11	import java.util.List;
12	import org.springframework.web.bind.annotation.PostMapping;
13	import org.springframework.web.bind.annotation.RequestBody;
14	import org.springframework.web.bind.annotation.RequestMapping;
15	import org.springframework.web.bind.annotation.RestController;
16	
17	/** Listing, adding and editing the claims on a sheet, and changing their status. */
18	@RestController
19	@RequestMapping("/api/claims")
20	public class ClaimController {
21	
22	    /** An amount: 0.00 or more, with up to two decimals. */
23	    public static final String AMOUNT = "\\d{1,12}(\\.\\d{1,2})?";
24	
25	    /** A claim's amount: as {@link #AMOUNT}, or below zero for a correction. */
26	    public static final String SIGNED_AMOUNT = "-?" + AMOUNT;
27	
28	    public record ListClaimsRequest(@NotBlank @Size(max = 100) String sheet) {
29	    }
30	
31	    public record AddClaimRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
32	            @NotNull Long personId, @NotNull @Pattern(regexp = SIGNED_AMOUNT) String amount, LocalDate date,
33	            @Size(max = 1000) String note, @Size(max = 120) String corrects) {
34	    }
35	
36	    public record UpdateClaimRequest(@NotBlank @Size(max = 100) String sheet,
37	            @NotBlank @Size(max = 100) String user, @NotNull Long id,
38	            @NotNull @Pattern(regexp = SIGNED_AMOUNT) String amount, LocalDate date, @Size(max = 1000) String note,
39	            @Size(max = 120) String corrects) {
40	    }
41	
42	    public record ClaimStatusRequest(@NotBlank @Size(max = 100) String sheet,
43	            @NotBlank @Size(max = 100) String user, @NotNull Long id) {
44	    }
45	
46	    public record RejectClaimRequest(@NotBlank @Size(max = 100) String sheet,
47	            @NotBlank @Size(max = 100) String user, @NotNull Long id,
48	            @NotBlank @Size(max = 200) @Pattern(regexp = "\\s*\\S+\\s*") String reason) {
49	    }
50	
51	    public record BulkOpenRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
52	            @NotNull @Size(max = 1000) List<@NotNull Long> ids) {
53	    }
54	
55	    public record BulkOpenResponse(int opened, int refused, List<ClaimResponse> claims) {
56	    }
57	
58	    public record ClaimResponse(long id, long personId, String amount, LocalDate date, String note,
59	            ClaimStatus status, String number, String settledDue, String openedBy,
60	            boolean stated, String statedDue, String corrects) {
61	    }
62	
63	    private static String money(BigDecimal value) {
64	        return value == null ? null : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
65	    }
66	
67	    public static ClaimResponse response(Claim claim) {
68	        return new ClaimResponse(claim.getId(), claim.getPersonId(),
69	                claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(), claim.getDate(),
70	                claim.getNote(), claim.getStatus(), claim.getNumber(),
71	                money(claim.getSettledDue()), claim.getOpenedBy(), claim.isStated(), money(claim.getStatedDue()),
72	                claim.getCorrects());
73	    }
74	
75	    public static BigDecimal amount(String amount) {
76	        return new BigDecimal(amount).setScale(2, RoundingMode.UNNECESSARY);
77	    }
78	
79	    /** The number a correction names, trimmed; null when none is named. */
80	    private static String corrects(String corrects) {
81	        return corrects == null || corrects.isBlank() ? null : corrects.trim();
82	    }
83	
84	    private static String note(String note) {
85	        return note == null ? "" : note.trim();
86	    }
87	
88	    private final ClaimService service;
89	
90	    public ClaimController(ClaimService service) {
91	        this.service = service;
92	    }
93	
94	    @PostMapping("/list")
95	    public List<ClaimResponse> list(@Valid @RequestBody ListClaimsRequest req) {
96	        return service.list(req.sheet().trim()).stream().map(ClaimController::response).toList();
97	    }
98	
99	    @PostMapping("/add")
100	    public ClaimResponse add(@Valid @RequestBody AddClaimRequest req) {
101	        return response(service.add(req.sheet().trim(), req.user().trim(), req.personId(), amount(req.amount()), req.date(),
102	                note(req.note()), corrects(req.corrects())));
103	    }
104	
105	    @PostMapping("/update")
106	    public ClaimResponse update(@Valid @RequestBody UpdateClaimRequest req) {
107	        return response(service.update(req.sheet().trim(), req.user().trim(), req.id(), amount(req.amount()), req.date(),
108	                note(req.note()), corrects(req.corrects())));
109	    }
110	
