370	/**
371	 * The claims on a sheet: added to a person and edited (amount, date, note). A claim given no date
372	 * takes the sheet's today. A claim starts as DRAFT and moves through its statuses (see
373	 * {@link ClaimStatus}); a change its status does not allow is refused. Only a DRAFT can be edited:
374	 * to change an open claim, void it and add a new one. Settling a claim fixes its
375	 * due at the rate its person's grade has then for the claim's date; an open claim's due stays live.
376	 * A claim records who opened it, and that user cannot settle it (four eyes). A claim bound by its
377	 * person's last statement keeps the figure it had then, and settling it fixes that figure. No claim
378	 * dated inside a closed period can be added, edited (to or from such a date) or change status. No
379	 * claim can be added or edited to a date after its person's retirement date. A clerk settles a claim
380	 * only when its figure is at or below the sheet's clerk limit (a claim with no figure is within any
381	 * limit); a clerk settling one above it makes it PENDING instead. A steward settles any claim, and
382	 * approves a PENDING claim (SETTLED, its due fixed then) or rejects it with a reason (back to OPEN);
383	 * the user who opened a claim cannot approve it. A PENDING claim is not bound by a statement: it
384	 * shows its live figure, and is bound again by the last statement once rejected. A claim's live due is never below the sheet's floor. An
385	 * overdue claim's due gains a late charge on top of its figure (see {@link LateCharge}); a statement
386	 * binds only the figure under it, and settling fixes the charge into the settled due. A claim with
387	 * a negative amount is a correction: it is allowed only when it names, by number, a SETTLED claim
388	 * of the same person that it corrects. Its due has no floor and no late charge.
389	 */
390	@Service
391	public class ClaimService {
392	
393	    private final ClaimRepository claims;
394	    private final PersonRepository people;
395	    private final RateRepository rates;
396	    private final SheetService sheets;
397	    private final Audit audit;
398	    private final RollupService rollup;
399	    private final PeriodService periods;
400	    private final RoleService roles;
401	
402	    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates, SheetService sheets,
403	            Audit audit, RollupService rollup, PeriodService periods, RoleService roles) {
404	        this.roles = roles;
405	        this.rollup = rollup;
406	        this.periods = periods;
407	        this.claims = claims;
408	        this.people = people;
409	        this.rates = rates;
410	        this.sheets = sheets;
411	        this.audit = audit;
412	    }
413	
414	    /**
415	     * A claim's figure under any late charge: the due fixed when settled, else the one bound by a
416	     * statement (not while PENDING), else the live due; null when it has none.
417	     */
418	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
419	        if (claim.getStatus() == ClaimStatus.SETTLED) {
420	            return claim.getSettledDue();
421	        }
422	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
423	                : due(sheetId, person, claim);
424	    }
425	
426	    /** A claim's figure with its late charge on the sheet's today added on top; null when it has none. */
427	    public BigDecimal charged(String sheetId, Person person, Claim claim) {
428	        return LateCharge.withCharge(sheets.sheet(sheetId), claim, figure(sheetId, person, claim));
429	    }
430	
431	    @Transactional(readOnly = true)
432	    public List<Claim> list(String sheetId) {
433	        return claims.findBySheetIdOrderByIdDesc(sheetId);
434	    }
435	
436	    @Transactional
437	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
438	            String corrects) {
439	        Person person = person(sheetId, personId);
440	        LocalDate dated = dateOrToday(sheetId, date);
441	        periods.refuseIfClosed(sheetId, dated);
442	        refuseIfRetired(person, dated);
443	        String corrected = corrected(sheetId, personId, amount, corrects);
444	        RollupService.Snapshot before = rollup.snapshot(sheetId);
445	        Claim added = claims.saveAndFlush(new Claim(sheetId, personId, amount, dated, note, corrected));
446	        audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, added));
447	        rollup.recordChanges(sheetId, user, before);
448	        return added;
449	    }
450	
451	    @Transactional
452	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
453	            String corrects) {
454	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
455	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
456	        if (claim.getStatus() != ClaimStatus.DRAFT) {
457	            throw new ResponseStatusException(HttpStatus.CONFLICT,
458	                    "A " + claim.getStatus() + " claim cannot be edited.");
459	        }
460	        LocalDate dated = dateOrToday(sheetId, date);
461	        periods.refuseIfClosed(sheetId, claim.getDate());
462	        periods.refuseIfClosed(sheetId, dated);
463	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
464	        String corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
465	        RollupService.Snapshot before = rollup.snapshot(sheetId);
466	        claim.setAmount(amount);
467	        claim.setDate(dated);
468	        claim.setNote(note);
469	        claim.setCorrects(corrected);
470	        Claim saved = claims.saveAndFlush(claim);
471	        audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
472	        rollup.recordChanges(sheetId, user, before);
473	        return saved;
474	    }
475	
476	    /**
477	     * Move a claim to a new status, refused (409) when its current status does not allow it, and
478	     * refused (403) when the user who opened it tries to settle it. A clerk settling one whose
479	     * figure is above the sheet's clerk limit makes it PENDING instead.
480	     */
481	    @Transactional
482	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
483	        return changeStatus(sheetId, user, id, next, null, false);
484	    }
485	
486	    /**
487	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure with its late
488	     * charge on the sheet's today. Refused (409) when not PENDING, and (403) for a clerk or the
489	     * user who opened it.
490	     */
491	    @Transactional
492	    public Claim approve(String sheetId, String user, long id) {
493	        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, true);
494	    }
495	
496	    /**
497	     * Reject a PENDING claim with a reason: it is OPEN again, bound again by the last statement if
498	     * that statement included it. Refused (409) when not PENDING, and (403) for a clerk.
499	     */
500	    @Transactional
501	    public Claim reject(String sheetId, String user, long id, String reason) {
502	        return changeStatus(sheetId, user, id, ClaimStatus.OPEN, reason, true);
503	    }
504	
505	    /** Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING claim. */
506	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
507	            boolean review) {
508	        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
509	        if (next == ClaimStatus.OPEN) {
510	            sheets.lock(sheetId);
511	        }
512	        RollupService.Snapshot before = rollup.snapshot(sheetId);
513	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
514	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
515	        ClaimStatus was = claim.getStatus();
516	        // only a steward's review moves a PENDING claim on, other than voiding it
517	        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))) {
518	            throw new ResponseStatusException(HttpStatus.CONFLICT,
519	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
520	        }
521	        periods.refuseIfClosed(sheetId, claim.getDate());
522	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
523	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
524	                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
525	        }
526	        if (review && !isSteward(sheetId, user)) {
527	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
528	                    "Only a steward can approve or reject a PENDING claim.");
529	        }
530	        Person person = person(sheetId, claim.getPersonId());
531	        // settling fixes the figure with its late charge as it stands on the sheet's today (a
532	        // PENDING claim's figure is live)
533	        BigDecimal settling = next == ClaimStatus.SETTLED ? charged(sheetId, person, claim) : null;
534	        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, settling)) {
535	            next = ClaimStatus.PENDING;
536	            settling = null;
537	        }
538	        claim.setStatus(next);
539	        if (next == ClaimStatus.OPEN && !review) {
540	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDate()));
541	            claim.setOpenedBy(user);
542	        } else if (next == ClaimStatus.SETTLED) {
543	            claim.setSettledDue(settling);
544	        }
545	        Claim saved = claims.saveAndFlush(claim);
546	        String event = switch (next) {
547	            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
548	            case PENDING -> "CLAIM_PENDING";
549	            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
550	            case VOID -> "CLAIM_VOIDED";
551	            case DRAFT -> throw new IllegalStateException();
552	        };
553	        audit.recordOnCommit(record(event, sheetId, user, person, saved)
554	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
555	                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
556	                + (reason != null ? " reason=" + reason : ""));
557	        rollup.recordChanges(sheetId, user, before);
558	        return saved;
559	    }
560	
561	    /** What a bulk open did: how many claims were opened and how many refused, and the claims opened. */
562	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
563	    }
564	
565	    /**
566	     * Open the given claims together, in list order (the order people were added, newest claim
567	     * first within a person), so they are numbered in that order. A claim that cannot be opened
568	     * (not on the sheet, not DRAFT, or dated inside a closed period) is refused and left as it is.
569	     */
570	    @Transactional
571	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> ids) {
572	        Map<Long, Integer> personOrder = new HashMap<>();
573	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
574	        for (int i = 0; i < listed.size(); i++) {
575	            personOrder.put(listed.get(i).getId(), i);
576	        }
577	        List<Claim> selected = ids.stream().distinct()
578	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
579	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
580	                        .thenComparing(Claim::getId, Comparator.reverseOrder()))
581	                .toList();
582	        int refused = (int) ids.stream().distinct().count() - selected.size();
583	        List<Claim> opened = new ArrayList<>();
584	        for (Claim claim : selected) {
585	            if (claim.getStatus() != ClaimStatus.DRAFT || periods.isClosed(sheetId, claim.getDate())) {
586	                refused++;
587	                continue;
588	            }
589	            opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
590	        }
591	        return new BulkOpened(opened.size(), refused, opened);
592	    }
593	
594	    /**
595	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date,
596	     * rounded to the cent as the claim rounds (see {@link Rounding}) and raised to the sheet's floor (a correction's is not); null with no
597	     * rate in force then.
598	     */
599	    public BigDecimal due(String sheetId, Person person, Claim claim) {
600	        Sheet sheet = sheets.sheet(sheetId);
601	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
602	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
603	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
604	                .map(due -> claim.isCorrection() ? due : due.max(sheet.getFloor()))
605	                .orElse(null);
606	    }
607	
608	    /** The date a claim rounds by: its own, or for a correction that of the claim it corrects. */
609	    private LocalDate roundingDate(String sheetId, Claim claim) {
610	        if (!claim.isCorrection() || claim.getCorrects() == null) {
611	            return claim.getDate();
612	        }
613	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
614	    }
615	
616	    private static String dueText(BigDecimal due) {
617	        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
618	    }
619	
620	    /** Whether the user is a clerk settling a claim whose figure is above the sheet's clerk limit. */
621	    private boolean aboveClerkLimit(String sheetId, String user, BigDecimal figure) {
622	        BigDecimal limit = sheets.clerkLimit(sheetId);
623	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
624	    }
625	
626	    private boolean isSteward(String sheetId, String user) {
627	        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
628	    }
629	
630	    /**
631	     * The number a claim corrects: none unless its amount is negative, when it must name the number
632	     * of a SETTLED claim of the same person, else it is refused (400).
633	     */
634	    private String corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
635	        if (amount.signum() >= 0) {
636	            return null;
637	        }
638	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
639	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
640	        if (!settled) {
641	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
642	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
643	        }
644	        return corrects;
645	    }
646	
647	    /** Refuse (422) a claim dated after its person's retirement date. */
648	    private static void refuseIfRetired(Person person, LocalDate date) {
649	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
650	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
651	                    "That claim's date is after its person's retirement date.");
652	        }
653	    }
