655	    private Person person(String sheetId, long personId) {
656	        return people.findByIdAndSheetId(personId, sheetId)
657	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
658	    }
