660	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
661	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName() + " amount="
662	                + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + " date=" + claim.getDate();
663	    }
