671	/**
672	 * A claim's status: DRAFT when added; opened (OPEN), then settled (SETTLED). A clerk settling a
673	 * claim above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or
674	 * rejects it (back to OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID). A SETTLED or VOID
675	 * claim cannot change status.
676	 */
677	public enum ClaimStatus {
678	    DRAFT, OPEN, PENDING, SETTLED, VOID;
679	
680	    /** Whether a claim in this status may move to the given one. */
681	    public boolean canBecome(ClaimStatus next) {
682	        return switch (next) {
683	            case OPEN -> this == DRAFT || this == PENDING;
684	            case PENDING -> this == OPEN;
685	            case SETTLED -> this == OPEN || this == PENDING;
686	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
687	            case DRAFT -> false;
688	        };
689	    }
690	
691	    /** Whether a claim in this status counts toward the totals: OPEN, PENDING and SETTLED do. */
692	    public boolean counts() {
693	        return this == OPEN || this == PENDING || this == SETTLED;
694	    }
695	
696	    /** Whether a claim in this status is open: OPEN or PENDING (it goes overdue, and a hold takes it out of the totals). */
697	    public boolean isOpen() {
698	        return this == OPEN || this == PENDING;
699	    }
700	}
