704	import java.time.LocalDate;
705	import java.time.temporal.ChronoUnit;
706	import net.officefloor.hq.app.sheet.Sheet;
707	
708	/**
709	 * The late charge on an overdue claim: the sheet's late percent of the claim's figure for every
710	 * full 30 days it is overdue (OPEN or PENDING, and past its date plus the sheet's terms on the sheet's today),
711	 * rounded to the cent as the claim rounds (see {@link Rounding}). A correction has none. Never bound by a statement; settling a claim fixes it into its due.
712	 */
713	public final class LateCharge {
714	
715	    /** The days overdue that each add one late percent. */
716	    private static final int PERIOD_DAYS = 30;
717	
718	    private LateCharge() {
719	    }
720	
721	    /** The figure with its late charge added on top; null when the figure is null. */
722	    public static BigDecimal withCharge(Sheet sheet, Claim claim, BigDecimal figure) {
723	        return figure == null ? null : figure.add(charge(sheet, claim, figure));
724	    }
725	
726	    /** The late charge on a claim's figure on the sheet's today; zero when it is not overdue. */
727	    public static BigDecimal charge(Sheet sheet, Claim claim, BigDecimal figure) {
728	        BigDecimal zero = BigDecimal.ZERO.setScale(2);
729	        if (figure == null || !claim.getStatus().isOpen() || claim.isCorrection()) {
730	            return zero;
731	        }
732	        LocalDate dueBy = claim.getDate().plusDays(sheet.getTerms());
733	        long periods = ChronoUnit.DAYS.between(dueBy, sheet.getToday()) / PERIOD_DAYS;
734	        if (periods <= 0) {
735	            return zero;
736	        }
737	        return figure.multiply(sheet.getLatePct()).multiply(BigDecimal.valueOf(periods))
738	                .divide(BigDecimal.valueOf(100), 2, Rounding.mode(sheet, claim.getDate()));
739	    }
740	}
