747	
748	/**
749	 * How a claim's live figures are rounded to the cent: half up when the claim is dated before the
750	 * sheet's policy date (its today when it has none), half to even when dated on or after it. A
751	 * correction rounds by the date of the claim it corrects, not its own.
752	 */
753	public final class Rounding {
754	
755	    private Rounding() {
756	    }
757	
758	    /** The rounding for a claim dated on the given date. */
759	    public static RoundingMode mode(Sheet sheet, LocalDate date) {
760	        LocalDate policy = sheet.getPolicyDate() != null ? sheet.getPolicyDate() : sheet.getToday();
761	        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
762	    }
763	
764	    /**
765	     * The date a claim rounds by: its own, or for a correction the date of the claim it corrects,
766	     * found by number among the sheet's claims (its own when that claim is not among them).
767	     */
768	    public static LocalDate dateOf(Claim claim, Collection<Claim> sheetClaims) {
769	        if (!claim.isCorrection() || claim.getCorrects() == null) {
770	            return claim.getDate();
771	        }
772	        return sheetClaims.stream().filter(c -> claim.getCorrects().equals(c.getNumber())).findFirst()
773	                .map(Claim::getDate).orElse(claim.getDate());
774	    }
775	}
