808	
809	    /** A person's statements: how many, and the last one (none before the first). */
810	    public record Summary(long personId, int count, Statement last) {
811	    }
812	
813	    /** A statement just taken, with the person's claims as it left them. */
814	    public record Taken(Summary summary, List<Claim> claims) {
815	    }
