824	    private final RollupService rollup;
825	
826	    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
827	            ClaimService claimService, RateRepository rates, SheetService sheets, Audit audit, RollupService rollup) {
828	        this.rollup = rollup;
829	        this.statements = statements;
830	        this.people = people;
831	        this.claims = claims;
832	        this.claimService = claimService;
833	        this.rates = rates;
834	        this.sheets = sheets;
835	        this.audit = audit;
836	    }
837	
838	    /** Each person's statements on the sheet who has taken any. */
839	    @Transactional(readOnly = true)
840	    public List<Summary> list(String sheetId) {
841	        Map<Long, Summary> by = new LinkedHashMap<>();
842	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
843	            Summary was = by.get(s.getPersonId());
844	            by.put(s.getPersonId(), new Summary(s.getPersonId(), was == null ? 1 : was.count() + 1, s));
845	        }
846	        return List.copyOf(by.values());
847	    }
848	
849	    @Transactional
850	    public Taken take(String sheetId, String user, long personId) {
851	        Person person = people.lockByIdAndSheetId(personId, sheetId)
852	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
853	        LocalDate today = sheets.today(sheetId);
854	        RollupService.Snapshot before = rollup.snapshot(sheetId);
855	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
856	        BigDecimal total = BigDecimal.ZERO.setScale(2);
857	        boolean anyFigure = false;
858	        int counted = 0;
859	        for (Claim claim : theirs) {
860	            if (person.counts(claim.getStatus())) {
861	                BigDecimal figure = claimService.figure(sheetId, person, claim);
862	                BigDecimal charged = claimService.charged(sheetId, person, claim);
863	                claim.bind(true, figure);
864	                if (charged != null) {
865	                    total = total.add(charged);
866	                    anyFigure = true;
867	                }
868	                counted++;
869	            } else {
870	                claim.bind(false, null);
871	            }
872	        }
873	        claims.saveAllAndFlush(theirs);
874	        // as on screen: n/a when the grade has no rate today and no claim that counts has a figure
875	        BigDecimal dueTotal = anyFigure || rates.findInForce(sheetId, person.gradeOn(today), today).isPresent() ? total
876	                : null;
877	        Statement taken = statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
878	        int count = (int) statements.findBySheetIdOrderByIdAsc(sheetId).stream()
879	                .filter(s -> Objects.equals(s.getPersonId(), personId)).count();
880	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
881	                + " due-total=" + money(dueTotal) + " claims=" + counted);
882	        rollup.recordChanges(sheetId, user, before);
883	        return new Taken(new Summary(personId, count, taken), theirs);
884	    }
